const items = $input.first().json.rss.channel.item;
const lista = Array.isArray(items) ? items : [items];

const limpiarHTML = (html = '') => String(html)
  .replace(/<[^>]*>/g, ' ')
  .replace(/Seguir leyendo/gi, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ')
  .trim();

const validas = lista
  .filter(n => n.link && n.link.includes('/tecnologia/') && !n.link.includes('/branded/'))
  .sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));

if (validas.length === 0) {
  throw new Error('No hay noticias válidas de tecnología en el feed');
}

const n = validas[0];

return [{
  json: {
    titulo: String(n.title).trim(),
    subtitulo: String(n.description || '').trim(),
    contenido: limpiarHTML(n['content:encoded']),
    link: n.link,
    fecha: n.pubDate,
    autor: String(n['dc:creator'] || '').trim(),
    categorias: [].concat(n.category || [])
  }
}];

